#!/usr/bin/env python3
"""build_recipe.py: assembles the study folder of every claimable leg and writes RUN-RECIPE.md (the claims for queue_add and the copy lines). Nothing is sent anywhere.

Run:  uv run --no-project python -I build_recipe.py
Reads orders/order-<leg>.json, cost_legs.json and the files of study/. Writes ~/build-scratch/pilot-permutation-20261124/studies/pilot164-<leg>/ (run_ab.sh, pilot_run.py,
probes.py, order.json, SHA256SUMS) and RUN-RECIPE.md (through RUN-RECIPE.md.new and a rename). Every claim, name and number of the recipe is read from those files.
"""
import hashlib
import json
import os
import shutil

HERE = os.path.dirname(os.path.abspath(__file__))
BUILD = os.path.expanduser("~/build-scratch/pilot-permutation-20261124")
LEGS = ("L0", "L1", "L2", "L3", "L4", "H")
cost = json.load(open(os.path.join(HERE, "cost_legs.json")))
SUMS = {}


def sha(path):
    return hashlib.sha256(open(path, "rb").read()).hexdigest()


lines = ["# Run recipe for the pilot of mmdbbench#164 on the mini (generated by build_recipe.py; no number or name below is typed)", "",
         "Private notes. Nothing here may be queued before the owner has posted the registration (PREREG.md, section 12) on #164. The claims are `queue_add` calls of the Humem Tower; each one prompts the owner, and the write tools allow 10 calls per hour per area (humem-ops docs/write-tools.md). A session that carries this out does not post the registration and does not queue before the owner says so.",
         "", "## Before the first claim", "",
         "1. Tower `status`: the mini has no job, no gate and no study, and its heartbeat is current. `solo`, `compare1`, `compare2` and `compare3` are in drive mode (the mini's `worker.toml` says so since 2026-11-23). Nothing else is queued on the mini.",
         "2. Nothing runs on the mini beside the pilot while a leg runs: no agent build, smoke or gate on any core (the rule of 2026-11-22: during a timed study only light work pinned to cores 18 and 19 from its first instruction, none at all while a leg runs).",
         "3. The sensor and the counters the runner reads exist on the mini (read on 2026-11-24: `coretemp` is hwmon3, `thermal_throttle/core_throttle_total_time_ms` and `package_throttle_total_time_ms` exist, `uv python list` has 3.12).",
         "4. The study folders are copied and checked (the copy lines of each leg).", "",
         "## Order of the legs", "",
         "| Leg | What | Claims | Hours low / central / high (cost_legs.py) |", "|---|---|---|---|"]
for leg in LEGS:
    c = cost[leg]
    lines.append(f"| {leg} | {c['title']} | {c['claims']} | {c['hours']['low']} / {c['hours']['central']} / {c['hours']['high']} |")
lines += ["", f"All six legs: {cost['claimable_now_hours']['low']} / {cost['claimable_now_hours']['central']} / {cost['claimable_now_hours']['high']} hours of host time (low / central / high), plus the time between stages. L0 first and read before anything else. L1 to L4 and H in any order after it; the registered order is the one above. Legs L5 and L6 (the real cells) are not claimable: `pilot_run.py` refuses them until the cell command is written and hashed (PREREG section 9).", ""]
n_claims = 0
for leg in LEGS:
    o = json.load(open(os.path.join(HERE, "orders", f"order-{leg}.json")))
    study = f"pilot164-{leg.lower()}"
    d = os.path.join(BUILD, "studies", study)
    os.makedirs(d, exist_ok=True)
    for f in ("run_ab.sh", "pilot_run.py", "probes.py"):
        shutil.copy(os.path.join(HERE, "study", f), os.path.join(d, f))
    shutil.copy(os.path.join(HERE, "orders", f"order-{leg}.json"), os.path.join(d, "order.json"))
    os.chmod(os.path.join(d, "run_ab.sh"), 0o755)
    names = ("run_ab.sh", "pilot_run.py", "probes.py", "order.json")
    open(os.path.join(d, "SHA256SUMS"), "w").write("".join(f"{sha(os.path.join(d, n))}  {n}\n" for n in names))
    SUMS[leg] = {n: sha(os.path.join(d, n)) for n in names}
    lines += [f"## Leg {leg}: {o['title']}", "",
              f"Study folder `{study}` on the mini (`~/humem-drill/repros/{study}/`). Order seed {o['seed']}, salt {o['salt']}, {len(o['units'])} units, {len(o['claims'])} claims. sha256 of `order.json`: `{SUMS[leg]['order.json']}`.", "",
              "Copy (from the laptop, key socket set; check before the first claim):", "", "```",
              "export SSH_AUTH_SOCK=/run/user/1000/gcr/.ssh",
              f"rsync -a {d}/ mini:humem-drill/repros/{study}/",
              f"ssh mini 'cd humem-drill/repros/{study} && sha256sum -c SHA256SUMS && bash -n run_ab.sh && ls -l run_ab.sh'", "```", "",
              "Claims, in this order. Queue one stage, wait until every `analysis.txt` of the stage exists, then queue the next stage. The three claims of a compare stage are queued together (within a few minutes; the lanes meet at a rendezvous that waits 30 minutes). `cell_class` is the class of the heaviest stream the lane plays in the leg; `none` means the parameter is left out.", "",
              "| Stage | `study` | `out` | `lane` | `cell_class` | `issue` |", "|---|---|---|---|---|---|"]
    for c in o["claims"]:
        lines.append(f"| {c['stage']} | `{c['study']}` | `{c['out']}` | `{c['lane']}` | {('`' + c['cell_class'] + '`') if c['cell_class'] else 'none'} | `{c['issue']}` |")
        n_claims += 1
    lines += ["", f"`note` of every claim of the leg: the text in the `note` field of `orders/order-{leg}.json` (at most 200 characters), for example `{o['claims'][0]['note']}`. `host` is `mini`.", "",
              "A compare stage whose rendezvous failed (a claim exits 4 because a lane never started; no unit ran) is queued again, all three claims, with `-r2` appended to every `out` (the runner finds the claim by the name without the suffix and gives the stage its own sync folder). Nothing else is ever queued twice.", "",
              "Wait line after a stage (read only):", "", "```",
              f"ssh mini 'ls -l humem-drill/repros/{study}/*/analysis.txt'", "```", "",
              "After the last stage (fetch and read):", "", "```",
              f"rsync -a mini:humem-drill/repros/{study}/ {BUILD}/results/{study}/",
              f"cd ~/repos/humemai/mmdbbench/.notes/bench/pilot-permutation-20261124 && uv run --no-project python -I analyze.py --order orders/order-{leg}.json --rows {BUILD}/results/{study} --out-dir {BUILD}/results/{study}-analysis", "```", ""]
    if leg not in ("L0", "H"):
        lines += [f"If `analysis.txt` lists units to replace: `uv run --no-project python -I plan.py topup --order orders/order-{leg}.json --invalid {BUILD}/results/{study}-analysis/invalid.json --out {BUILD}/results/order-{leg}-t1.json`, copy that file to the study folder as `order-t1.json`, queue the claims it prints (stages `t1c` and `t1s`), fetch again and run the analysis with `--topup`. One top-up stage per leg; a run that is invalid again stays invalid.", ""]
    if leg == "L0":
        lines += ["Read the rows of L0 before L1: every `ok`, the three lanes of a unit start within a second of each other (`t_start`), `cpus_allowed` equals `cpus_expected` in every row, `throttle_ms` is a number, `gate_ok` is true, and the claims of stage s2 overlapped in time. The rows of L0 carry `shortened` and are never data.", ""]
    if leg == "H":
        lines += ["Verdict by `analyze.py`: HEAT-PASS needs, in each of the three lanes, throttle at most 1 percent of the 1800 s and the package at most 88 C. HEAT-PASS is the evidence the owner needs before the 26.12.1 small pass uses three busy compare lanes; the pilot itself never has more than two busy lanes.", ""]
lines += ["## The results folder", "", f"`{BUILD}/results/` is on disk (not tmpfs). The rows files are the only input of `analyze.py`. Nothing from it is copied into a public place without the owner's word.", ""]
text = "\n".join(lines) + "\n"
bad = [c for c in ("—", "–") if c in text]
assert not bad, "dash in the recipe"
open(os.path.join(HERE, "RUN-RECIPE.md.new"), "w", encoding="utf-8").write(text)
os.replace(os.path.join(HERE, "RUN-RECIPE.md.new"), os.path.join(HERE, "RUN-RECIPE.md"))
json.dump(SUMS, open(os.path.join(HERE, "study-sums.json"), "w"), indent=1, sort_keys=True)
print(f"RUN-RECIPE.md written: {len(text.splitlines())} lines, {n_claims} claims in {len(LEGS)} legs; study folders in {BUILD}/studies")
